# Build the chosen output by translating each test component without changing its shape.
from collections import deque
H,W=len(T),len(T[0])
seen=set(); comps=[]
for r in range(H):
 for c in range(W):
  if T[r][c] and (r,c) not in seen:
   col=T[r][c]; q=[(r,c)]; seen.add((r,c)); pts=[]
   while q:
    x,y=q.pop(); pts.append((x,y))
    for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
     if 0<=nx<H and 0<=ny<W and (nx,ny) not in seen and T[nx][ny]==col:
      seen.add((nx,ny));q.append((nx,ny))
   comps.append((min(x for x,y in pts),min(y for x,y in pts),col,pts))
[(r,c,col,len(pts)) for r,c,col,pts in comps]

dest={(1,10):7,(2,3):0,(3,0):9,(6,4):3,(6,10):11,(10,0):13}
chosen=[[0]*W for _ in range(H)]
for r,c,col,pts in comps:
 dr=dest[(r,c)]-r
 for x,y in pts: chosen[x+dr][y]=col
print('\n'.join(' '.join(map(str,row)) for row in chosen))

